package com.collabboard.security;
import io.jsonwebtoken.*;import io.jsonwebtoken.security.Keys;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import javax.crypto.SecretKey;import java.nio.charset.StandardCharsets;import java.time.Instant;import java.util.Date;
@Service public class JwtService {private final SecretKey key;private final long ttl;public JwtService(@Value("${app.jwt.secret}")String secret,@Value("${app.jwt.ttl-ms:86400000}")long ttl){if(secret==null||secret.getBytes(StandardCharsets.UTF_8).length<32)throw new IllegalStateException("JWT_SECRET must contain at least 32 UTF-8 bytes");key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));this.ttl=ttl;}public String issue(AuthPrincipal p){Instant now=Instant.now();return Jwts.builder().subject(p.id()).claim("name",p.displayName()).claim("email",p.email()).claim("ver",p.tokenVersion()).issuedAt(Date.from(now)).expiration(Date.from(now.plusMillis(ttl))).signWith(key).compact();}public AuthPrincipal parse(String token){Claims c=Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload();Integer version=c.get("ver",Integer.class);return new AuthPrincipal(c.getSubject(),c.get("name",String.class),c.get("email",String.class),version==null?0:version);}public long ttl(){return ttl;}}
